/// </summary>
/// <returns>
///    <c>UnitIDBase</c> as return value
/// </returns>
[SysClientCacheDataMethodAttribute(true)]
display UnitIDBase displayAVAUnitId()
{
    UnitIDBase          retVal;
    //InventTransOrigin   locInventTransOrigin;

    //locInventTransOrigin = InventTransOrigin::findByInventTransId(this.InventTransId);
    /*
    if(this.InventTransId)
    {
        switch(this.InventTransType)
        {
            case InventTransType::Sales:
                retVal  = SalesLine::findInventTransId(this.InventTransId).SalesUnit;
                break;

            case InventTransType::Purch:
                retVal  = PurchLine::findInventTransId(this.InventTransId).PurchUnit;
                break;

            case InventTransType::InventTransfer:
                retVal  = InventTransferLine::findTransIdShip(this.InventTransId).UnitId;
                break;

            default:
                retVal = InventTable::find(this.ItemId).inventUnitId();
        }
    }
    */
    retVal = InventTable::find(this.ItemId).inventUnitId();

    return retVal;
}
